```cpp
#include <iostream>
#include <string>
#include <regex>

// Fonction pour convertir du texte au format Markdown en HTML
std::string markdown_to_html(const std::string& markdown) {
    // Création des expressions régulières pour les balises Markdown
    std::regex heading_regex{"^#{1,6}\\s+(.+)$", std::regex::icase}; // # pour les titres
    std::regex italic_regex{"\\*(.+?)\\*"}; // * pour le gras
    std::regex bold_regex{"\\**(.+?)\\**"}; // ** pour le souligné
    std::regex link_regex{"\\[\\s*(.+?)\\s*\\]\\(\\s*(.+?)\\s*\\)"}; // [texte](url)
    std::regex image_regex{"!\\[\\s*(.+?)\\s*\\]\\(\\s*(.+?)\\s*\\)"}; // ![alt](url)

    // Création du texte HTML à partir du texte Markdown
    std::string html;
    html.reserve(markdown.size()); // Optimiser la taille du buffer

    bool inside_code_block = false;
    for (char c : markdown) {
        if (c == '`') {
            inside_code_block = !inside_code_block;
            html += inside_code_block ? "<code>" : "</code>";
        } else if (inside_code_block) {
            html += c;
        } else {
            std::string match;

            if (std::regex_match(c, match, std::regex{"^#"})) {
                // Titre
                int level = match.length();
                std::smatch matches;
                if (std::regex_search(markdown.substr(1), matches, heading_regex)) {
                    html += "<h" + std::to_string(level) + ">" + matches[1] + "</h" + std::to_string(level) + ">\n";
                }
            } else if (std::regex_match(c, match, std::regex{"^\\*"})) {
                // Gras
                std::smatch matches;
                if (std::regex_search(markdown.substr(1), matches, italic_regex)) {
                    html += "<strong>" + matches[1] + "</strong>";
                }
            } else if (std::regex_match(c, match, std::regex{"^\\**"})) {
                // Souligné
                std::smatch matches;
                if (std::regex_search(markdown.substr(2), matches, bold_regex)) {
                    html += "<em>" + matches[1] + "</em>";
                }
            } else if (std::regex_match(c, match, std::regex{"^\\["})) {
                // Lien
                std::smatch link_matches;
                if (std::regex_search(markdown.substr(1), link_matches, link_regex)) {
                    std::string link_text = link_matches[1];
                    std::string link_url = link_matches[2];
                    html += "<a href=\"" + link_url + "\">" + link_text + "</a>";
                }
            } else if (std::regex_match(c, match, std::regex{"^!\\["})) {
                // Image
                std::smatch image_matches;
                if (std::regex_search(markdown.substr(2), image_matches, image_regex)) {
                    std::string alt_text = image_matches[1];
                    std::string image_url = image_matches[2];
                    html += "<img src=\"" + image_url + "\" alt=\"" + alt_text + "\" />";
                }
            } else {
                html += c;
            }
        }
    }

    return html;
}

int main() {
    std::string markdown = "## Titre H2\n\nTexte *gras* et **souligné**.\n\n[lien](https://example.com) et ![image](image.jpg)";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Cette fonction utilise des expressions régulières pour détecter les balises Markdown et les convertir en HTML. Elle prend en compte les titres, le gras, le souligné, les liens et les images. Les balises HTML sont générées dynamiquement en fonction du contenu du texte Markdown. 

Cependant, cette fonction n'est pas exhaustive et ne couvre pas toutes les possibilités du Markdown. Il est recommandé de consulter les spécifications du Markdown pour obtenir une implémentation complète.

